window.B0B_INTRO_CHAPTERS=[{"id": "I", "title": "The father", "year": "1991", "at": 0.0, "end": 34.273, "map": false, "lines": [{"text": "Robert Maxwell. A Military Cross in 1945; from 1951, Pergamon Press - scientific publishing that crossed the Iron Curtain.", "at": 0.35, "end": 8.932}, {"text": "In 1971 government inspectors wrote that he was not a person who could be relied on to exercise proper stewardship of a publicly quoted company.", "at": 9.382, "end": 17.969}, {"text": "On 5 November 1991 he vanished from his yacht off the Canary Islands. Within weeks, more than four hundred million pounds was found missing from his companies’ pension funds.", "at": 18.419, "end": 29.246}, {"text": "He was buried on the Mount of Olives. The President of Israel gave the eulogy.", "at": 29.696, "end": 33.573}]}, {"id": "II", "title": "The year", "year": "1991", "at": 34.273, "end": 50.929, "map": false, "lines": [{"text": "In July 1991 Leslie Wexner gave Epstein power of attorney: to sign cheques, hire, and buy and sell property in his name.", "at": 34.623, "end": 43.314}, {"text": "1991 is when Epstein became useful. It is no evidence of when, or whether, anyone recruited him.", "at": 43.764, "end": 50.229}]}, {"id": "III", "title": "The complaint", "year": "2025", "at": 50.929, "end": 64.26, "map": false, "lines": [{"text": "In September 1996 the FBI logged a complaint about Epstein. It stayed out of public view until the Justice Department released it in December 2025.", "at": 51.279, "end": 61.238}, {"text": "Nothing followed for nine years.", "at": 61.688, "end": 63.56}]}, {"id": "IV", "title": "The deal", "year": "2020", "at": 64.26, "end": 102.074, "map": false, "lines": [{"text": "Palm Beach, 2005: police open a case. In September 2007 federal prosecutors agree to end their investigation, and to forgo prosecuting him, four named co-conspirators, and any potential co-conspirators.", "at": 64.61, "end": 78.588}, {"text": "In 2008 he pleads guilty to two state charges, and serves less than thirteen months, much of it on work release.", "at": 79.038, "end": 86.222}, {"text": "In 2019 a federal judge rules that prosecutors violated the victims’ rights law by failing to tell them of the deal. In 2020 the Justice Department’s own review found that the US Attorney, Alexander Acosta, had shown poor judgment.", "at": 86.672, "end": 101.374}]}, {"id": "V", "title": "The pipe", "year": "2023", "at": 102.074, "end": 124.144, "map": false, "lines": [{"text": "JPMorgan banked him for fifteen years, and kept him through two waves of red flags.", "at": 102.424, "end": 107.286}, {"text": "Only after his arrest in 2019 did it file reports flagging about one point three billion dollars in transfers.", "at": 107.736, "end": 115.015}, {"text": "It settled with his victims for two hundred and ninety million dollars, and with the Virgin Islands for seventy-five, admitting no liability.", "at": 115.465, "end": 123.445}]}, {"id": "VI", "title": "The cell", "year": "2025", "at": 124.144, "end": 175.414, "map": false, "lines": [{"text": "July 2019: arrested again, on federal sex-trafficking charges. On 10 August he was found dead in his cell.", "at": 124.494, "end": 131.799}, {"text": "The Inspector General found: a written direction to give him a cellmate ignored; half the cameras not recording; no rounds for hours; records falsified.", "at": 132.249, "end": 141.573}, {"text": "The medical examiner ruled suicide. A pathologist retained by the family disputes it. The ruling stands; the dissent is recorded.", "at": 142.023, "end": 149.914}, {"text": "States can move a person and give him a new name; that is on the record. What this record holds instead is an autopsy observed by the family’s own pathologist, and a family arguing murder, not survival.", "at": 150.364, "end": 162.873}, {"text": "In 2025 the Justice Department released raw footage of that night. It had been assembled from at least two clips. The editing is documented; what it hides, if anything, is not.", "at": 163.323, "end": 174.714}]}, {"id": "VII", "title": "The survivor", "year": "2026", "at": 175.414, "end": 208.733, "map": false, "lines": [{"text": "Ghislaine Maxwell was convicted in December 2021 on five counts, including sex trafficking of a minor, and sentenced to twenty years.", "at": 175.764, "end": 184.31}, {"text": "In July 2025 the Deputy Attorney General interviewed her for two days under limited immunity. A week later she was moved to a minimum-security prison camp.", "at": 184.76, "end": 194.093}, {"text": "In November 2025 Congress ordered the files released. The Department has published nearly three and a half million pages.", "at": 194.543, "end": 202.074}, {"text": "In the United States, only two people have ever been charged over the abuse. One of them is dead.", "at": 202.524, "end": 208.031}]}, {"id": "VIII", "title": "The question", "year": "2026", "at": 208.733, "end": 238.633, "map": false, "lines": [{"text": "The records that would settle what else this was are service files, and they are withheld from everyone. A silence that is certain to occur proves nothing either way.", "at": 209.083, "end": 217.877}, {"text": "This report’s conclusion: both functioned as deniable assets. Rung four.", "at": 218.327, "end": 222.602}, {"text": "It names a sponsor only as a hypothesis: Mossad directing, with American and British services witting by liaison - argued from documented structure, not from the files.", "at": 223.052, "end": 233.889}, {"text": "Rung five, tasked and run, is claimed for no one.", "at": 234.339, "end": 237.934}]}, {"id": "IX", "title": "The dates on paper", "year": "2026", "at": 238.633, "end": 253.302, "map": false, "lines": [{"text": "These are the dates on paper.", "at": 243.633, "end": 245.291}, {"text": "The trafficking is adjudicated. The rest is held at its tier.", "at": 245.741, "end": 249.302}]}];
window.B0B_INTRO_REEL_DUR=253.302;
